from production import *
def prepare_patch(n,b,base):
 D=W/base;m=read(D/'full.assembly.json');im=Image.open(m['candidate']['file']);origin=m['globalBox'][:2];crop=[b[0]-origin[0],b[1]-origin[1],b[2]-origin[0],b[3]-origin[1]];assert crop[2]-crop[0]==crop[3]-crop[1]==1254;p=W/'guides'/(n+'.target.png');assert not p.exists();im.crop(crop).save(p);write(str(p)+'.derivation.json',{'file':str(p),'sha256':sha(p),'globalNativeBox':b,'baseAssembly':str(D/'full.assembly.json'),'baseAssemblySha256':sha(D/'full.assembly.json'),'candidate':m['candidate'],'crop':crop,'nativeScale':1,'guideOnly':True});print(str(p))
def request_patch(n,scene):
 p=W/'guides'/(n+'.target.png');d=read(str(p)+'.derivation.json');refs=[p]+REFS;roles=['EDIT TARGET: exact native crop of current assembled image','REFERENCE: whole village layout only','REFERENCE: natural stone and architectural material detail only','PRIMARY REFERENCE: Q-style Daoist game painting']
 prompt='''Use case: precise-object-edit.
Asset type: one opaque exact native 1254x1254 close-up of an existing daylight isometric Q-style Daoist game map.
Input images: Image1 is the actual registered EDIT TARGET at native pixel scale; Image2 is layout only; Image3 is architectural/material detail only; Image4 is PRIMARY Q-style Daoist painting language only.
Primary request: Correct only the local broken texture/geometry joins in Image1. Preserve the exact camera, scale, coordinates, scene layout, material colors, highlight direction and every outer boundary anchor. This is a very close crop of a much larger map; never zoom out or recenter.
Targeted correction: '''+Path(scene).read_text(encoding='utf8')+'''
Constraints: exactly 1254x1254 opaque PNG, crisp hand-painted rounded game surfaces. Keep the outer 180-pixel perimeter and its anchored edge positions as unchanged as possible. Preserve all intact structures and details. Do not add or remove objects, change camera/roof pitch, shift a building, add interfaces, text, characters, watermarks, night lighting, photoreal noise, grids or transparency. No resizing.'''
 pp=W/'prompts'/(n+'.prompt.txt');assert not pp.exists();pp.write_text(prompt,encoding='utf8');write(W/'receipts'/(n+'.request.json'),{'requestedAtUtc':datetime.now(timezone.utc).isoformat(),'route':'builtin','tool':'image_gen.imagegen','globalNativeBox':d['globalNativeBox'],'promptFile':str(pp),'prompt':prompt,'referenced_image_paths':[str(x).replace('\\','/') for x in refs],'referenceRoles':roles,'references':[{'file':str(x).replace('\\','/'),'sha256':sha(x),'role':role} for x,role in zip(refs,roles)],'guideDerivation':{'file':str(p)+'.derivation.json','sha256':sha(str(p)+'.derivation.json')},'transparent_background':False,'actualModel':None,'actualQuality':None})
def save_patch(n):
 req=read(W/'receipts'/(n+'.request.json'));rec=read(W/'receipts'/(n+'.receipt.json'));original=Path(re.search(r' as (C:\\[^\n]+?\.png) by default',rec['output_hint']).group(1));p=W/'native'/(n+'.png');assert not p.exists();shutil.copy2(original,p);im=Image.open(p);assert im.size==(1254,1254);assert sha(p)==sha(original);assert im.mode!='RGBA' or im.getextrema()[3]==(255,255);b=req['globalNativeBox'];write(str(p)+'.generation.json',{'file':str(p),'sha256':sha(p),'generatedAtUtc':rec['returnedAtUtc'],'width':1254,'height':1254,'format':'PNG','route':'builtin','tool':'image_gen.imagegen','actualModel':None,'actualQuality':None,'unverifiedReason':'Built-in exposes no actual model/quality metadata.','globalNativeBox':b,'globalCoreBox':[b[0]+115,b[1]+115,b[2]-115,b[3]-115],'nativeCoreCropBox':[115,115,1139,1139],'nativeScaleResampled':False,'evidence':{'receipt':str(W/'receipts'/(n+'.receipt.json')),'receiptSha256':sha(W/'receipts'/(n+'.receipt.json')),'request':str(W/'receipts'/(n+'.request.json')),'requestSha256':sha(W/'receipts'/(n+'.request.json'))},'prompt':str(W/'prompts'/(n+'.prompt.txt')),'promptSha256':sha(W/'prompts'/(n+'.prompt.txt')),'references':req['references'],'toolOriginal':{'file':str(original),'sha256':sha(original)},'status':'patch-candidate-pending-composition-and-review'});print(json.dumps({'native':str(p),'sha256':sha(p)}))
if __name__=='__main__':
 if sys.argv[1]=='prepare':prepare_patch(sys.argv[2],list(map(int,sys.argv[3:7])),sys.argv[7])
 elif sys.argv[1]=='request':request_patch(sys.argv[2],sys.argv[3])
 elif sys.argv[1]=='save':save_patch(sys.argv[2])
